-- ESCO / Next Hire — Integracao SFIA 9 (habilidades, codigos e niveis 1-7)
-- ---------------------------------------------------------------------------
-- Gerado por /tmp/opencode/sfia9/generator.py a partir de:
--   - skills.json: 147 skills SFIA 9 raspadas de sfia-online.org (codigo, titulo,
--     guidance e descritores especificos por nivel)
--   - mapping.json: mapeamento SFIA -> habilidade ESCO (URI v1.2.0, via API hospedada)
--   - export_hab.csv / export_ocup.csv: dump do banco (habilidade, ocupacao+grupo)
--
-- Estrategia de niveis (ocupacao_habilidade.nivel_habilidade):
--   Cada skill SFIA define descritores apenas para seus niveis validos (faixa min..max).
--   O nivel por ocupacao e derivado por heuristica deterministica:
--     ISCO major 1 (chefia/direcao) -> topo da faixa
--     ISCO major 2 (profissionais)  -> minV + 75% da faixa
--     ISCO major 3+ (tecnicos/outros) -> minV + 40% da faixa
--     relacao essencial mantem o nivel base; opcional reduz 1 (respeitando a faixa).
--   Skills SFIA sem equivalente ESCO foram inseridas (uri sfia://CODIGO) e vinculadas
--   a ocupacoes por busca textual na API ESCO (tipo_relacionamento opcional).
--
INSERT INTO esco_dataset.nivel_habilidade (nivel, nome, descricao) VALUES
    (1, 'Seguir', 'Realiza tarefas de rotina sob supervisão direta, segue instruções e requer orientação para concluir o seu trabalho. Aprende e aplica habilidades e conhecimentos básicos. Autonomia: supervisionado de perto ou em instrução estruturada; influência: limitada a dizer o que fazer e quando; complexidade: tarefas de rotina e fáceis de executar; competências de negócio: foco em aprender e praticar.'),
    (2, 'Auxiliar', 'Presta assistência e fornece suporte a colegas, trabalhando sob supervisão de rotina. Exerce autonomia limitada nos detalhes de tarefas e processos e contribui para o trabalho da equipe. Autonomia: supervisionado de forma rotineira; influência: interage com a própria equipe e com colegas próximos; complexidade: tarefas de rotina, algumas não rotineiras; competências de negócio: entende a função no contexto imediato da equipe.'),
    (3, 'Aplicar', 'Trabalha sob direção geral, aplicando habilidades e conhecimentos na execução de tarefas de rotina e de alguma complexidade. Exerce autonomia limitada dentro de processos e procedimentos estabelecidos, registra e reporta resultados e identifica problemas no próprio trabalho. Autonomia: sob direção geral; influência: influencia as próprias escolhas de técnica e o trabalho de colegas próximos; complexidade: situações de rotina, algumas não rotineiras; competências de negócio: compreende a relação entre sua especialidade e a organização.'),
    (4, 'Capacitar', 'Trabalha sob direção limitada, influencia colegas e atua como ponto de contato dentro e fora da organização. Executa trabalhos de complexidade considerável, habilita e orienta outros profissionais em sua especialidade. Autonomia: sob direção limitada; influência: influencia colegas e organizações parceiras; complexidade: trabalhos diversos, incluindo alguns de complexidade considerável; competências de negócio: contribui para a melhoria das práticas de negócio e define padrões e procedimentos dentro da sua especialidade.'),
    (5, 'Assegurar, aconselhar', 'Fornece orientação e aconselhamento de referência em sua especialidade, trabalhando sob ampla direção. É responsável por resultados de trabalho significativos, do planejamento à execução e avaliação, e influencia a execução de projetos e atividades da organização. Autonomia: sob ampla direção; influência: influencia a organização e provedores externos; complexidade: desafios técnicos e de negócio de amplitude considerável; competências de negócio: entende a organização em profundidade e aconselha colegas de especialidades afins.'),
    (6, 'Iniciar, influenciar', 'Exerce autoridade e influência consideráveis sobre a organização, trabalhando sob ampla direção. Inicia e conduz atividades e mudanças significativas, desenvolve e comunica visões e estratégias de longo prazo e promove contribuições eficientes para o negócio. Autonomia: sob ampla direção ou dentro de uma política definida; influência: lidera formas de trabalho e influencia profissionais de alto nível; complexidade: explora e prevê desafios técnicos e de negócio de amplitude organizacional; competências de negócio: conhece o setor e a organização em profundidade.'),
    (7, 'Definir estratégia, inspirar, mobilizar', 'Opera no nível mais alto da organização, com autoridade para definir e comunicar a visão, a estratégia e a direção da mesma. Influencia políticas, lidera e mobiliza a organização e assume responsabilidade total por acertos e erros em todas as escalas e limites de decisão. Autonomia: completa, com poderes e responsabilidade ilimitados; influência: influencia políticas, líderes e profissionais de todos os níveis; complexidade: aplica o maior grau de perspicácia e visão de negócio; competências de negócio: lidera a direção estratégica da organização.')
ON CONFLICT (nivel) DO UPDATE SET nome = EXCLUDED.nome, descricao = EXCLUDED.descricao;

