-- Skills SFIA sem equivalente no ESCO: inseridas com uri sfia://CODIGO
INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://ACIN', 'Accessibility and inclusion', 'Activities may include, but are not limited to: providing expert advice and guidance on accessibility and inclusion defining policies, standards and guidelines for accessible design, development, user research, auditing and testing conducting accessibility impact assessments and audits to identify potential barriers and areas for improvement keeping up-to-date with the latest industry trends, regulatory developments and established practices related to accessibility collaborating with subject matter experts in areas such as usability, user experience, content design, assistive technology and disability rights advising teams on budgeting appropriately for accessibility activities throughout the service or product development lifecycle promoting a culture of shared responsibility for accessibility by embedding it into the roles and responsibilities of others, such, as designers, developers, researchers and managers.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'hardskill', 'ACIN')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://AIDE', 'Artificial intelligence (AI) and data ethics', 'Includes principles such as fairness, accountability, transparency and privacy. Ethical considerations encompass issues like bias in algorithms, data privacy, the impact of automation on employment and the societal implications of emerging technologies. Activities may include, but are not limited to: providing expert advice on ethical policies, procedures and governance designing AI and data systems that embed ethical considerations conducting ethical impact assessments to identify risks and ensure responsible use of technology responding to ethical dilemmas and incidents keeping up to date with ethical standards, regulations and recommended practices creating ethical risk models and frameworks collaborating with experts in fields such as legal, public relations, data science and AI promoting a culture of ethical awareness and responsibility within the organisation.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'hardskill', 'AIDE')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://ANCC', 'Analytical classification and coding', 'This skill is applied in contexts where consistent categorisation of information is required to enable the data to be used reliably and effectively. This may include, but is not limited to, clinical coding, data labelling for machine learning, legal coding/indexing and market research coding. Activities may include, but are not limited to: analysing and interpreting information based on domain-specific knowledge assigning codes, labels or categories based on specific standards, guidelines or frameworks ensuring accuracy and consistency of coding/labelling through quality assurance activities collaborating with subject matter experts to clarify ambiguous cases and improve coding/labelling guidelines providing guidance and training to others on coding/labelling practices contributing to the development and improvement of coding/labelling systems, guidelines and processes.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'hardskill', 'ANCC')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://ADEV', 'Animation development', 'Animation development enables the creation of visually engaging and interactive experiences for various industries, such as gaming, training, scientific research and engineering, as well as virtual reality and augmented reality applications. Components of animation systems include game engine or framework, visual assets (3D models, 2D artwork, animations), audio assets, user interface and user experience components, game logic, data and configuration files, tools and pipelines, documentation and design documents Activities may include, but are not limited to: employing animation techniques, including keyframe animation, motion capture, procedural animation and skeletal animation using specialised software for rigging, skinning and animation editing creating and integrating animations into interactive systems ensuring integration of animations with game logic, physics and artificial intelligence systems optimising animations for performance and adhering to consistency and quality standards.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'hardskill', 'ADEV')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://ASUP', 'Application support', 'Activities may include, but are not limited to: investigating and resolving issues implementing working practices to support iterative/agile development and/or cloud-based applications monitoring performance and maintaining the security of applications providing guidance or training to users, including enhanced levels of support following new/updated software releases devising permanent or temporary corrections, workarounds for faults, and applying patches when necessary adhering to established safety, security and quality standards capturing user feedback for subsequent analysis to inform future application development implementing general or site-specific modifications updating documentation maintaining application data defining enhancements. Support typically involves close collaboration with application developers and other specialist areas. Application maintenance and support services may be delivered directly to users of the systems or to service delivery functions.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'hardskill', 'ASUP')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://AVMT', 'Availability management', 'Activities may include, but are not limited to: defining and agreeing availability targets disaster recovery planning and testing ensuring services can collect data required to measure availability monitoring, analysing and reporting on service availability implementing availability management practices, including those for cloud-based services maintaining and improving the availability of services controlling and managing service availability to deliver agreed levels of availability in a cost-effective manner.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'hardskill', 'AVMT')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://BENM', 'Benefits management', 'Activities may include, but are not limited to: implementing a benefits management framework and approach identifying and implementing the actions needed to optimise the business impact of individual and combined benefits confirming the achievement of expected benefits adapting benefits management practices for agile projects using data-driven analysis for benefits identification, tracking and reporting engaging stakeholders to embed a value-driven culture.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'hardskill', 'BENM')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://BIDM', 'Bid/proposal management', 'Activities may include, but are not limited to: assessing requirements, conditions and customer needs relevant to the proposal or bid developing and implementing bid and proposal strategies, including competitive positioning leading multidisciplinary teams in crafting detailed, high-quality and persuasive proposal documents managing bid and proposal teams, resources, risks and issues throughout the proposal lifecycle overseeing compliance with legal, accessibility, customer and organisational requirements coordinating stakeholder engagement, communication and proposal reviews/approvals advocating for effective practices and innovative approaches in proposal development negotiating and closing deals with customers and stakeholders. This skill is applicable in diverse contexts, such as commercial organisations bidding for contracts and public sector entities seeking funding. In commercial settings, it emphasises competitive positioning and market strategies. In the public sector, it focuses on aligning with policy objectives and demonstrating public value. The core activities are consistent across different environments.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'hardskill', 'BIDM')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://BUDF', 'Budgeting and forecasting', 'Activities may include, but are not limited to: gathering and analysing financial data to prepare budgets and forecasts selecting and applying appropriate budgeting and forecasting methodologies and tools incorporating scenario planning, sensitivity analysis and risk assessment into the budgeting and forecasting process presenting budget and forecast information to stakeholders and facilitating data-driven decision-making developing and implementing budgeting and forecasting strategies, policies and processes aligned with organisational objectives driving the adoption of good practices providing strategic insights and recommendations based on budget and forecast analysis ensuring compliance with accounting standards, governance, legal and regulatory requirements applying budgeting and forecasting to cloud computing and FinOps contexts, such as consumption-based pricing, rapid scalability, and the need for real-time cost-visibility and optimisation.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'hardskill', 'BUDF')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://ADMN', 'Business administration', 'The application of this skill varies widely depending on role and organisation context. Business administration tasks may include: communication management, information organisation, scheduling and coordination with internal and external stakeholders using various digital tools and platforms. Management-level business administration tasks focus on planning, managing and coordinating the activities of individuals and teams to enable them to achieve their objectives efficiently and effectively. Activities may include, but are not limited to: managing calendars and scheduling meetings organising and maintaining filing systems (physical and digital) preparing reports, presentations and correspondence coordinating travel arrangements and expense management managing office supplies and equipment facilitating internal and external communications supporting project management activities assisting with budget preparation and monitoring implementing and maintaining administrative processes and procedures.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'hardskill', 'ADMN')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://BSMO', 'Business modelling', 'Predominantly focused on the representation of processes, roles, data, organisation and time. Models may be used to represent a subject at varying levels of detail and decomposition. Business models are typically created to communicate and provide insights into existing, conceptual or proposed scenarios. As such, they are likely to be working models that allow comparisons of alternative outcomes based on changing inputs and parameters. Activities may include, but are not limited to: gathering and analysing business requirements creating visual representations of business workflows, processes and structures developing and testing simulation models facilitating workshops to validate and refine models presenting models to stakeholders and explaining their implications. This skill shouldn''t be applied to the creation of all diagrams related to describing and explaining business concepts. Refer to other SFIA skills, including, but not limited to: Business situation analysis, Business process improvement, Data design and modelling, Enterprise and business architecture, Organisation design.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'hardskill', 'BSMO')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://CPMG', 'Capacity management', 'Service components include, but are not limited to, hardware, software, network resources and software/infrastructure as a service. Activities may include, but are not limited to: planning, design and management of the capability, performance, functionality and sustainability of service components to meet business needs applying data-driven insights to model long-term changes and short-term variations in the level of capacity required to execute the service implementing capacity management practices to support cloud-based services and ensure flexible and scalable capacity deploying techniques to control the demand and add/reduce capacity in a cost-effective, timely manner to meet changes in demand collaborating closely with other processes and teams to ensure a holistic approach to capacity management considering external factors, such as regulatory requirements and market trends, when planning and managing capacity continuously monitoring and optimising resource utilisation to identify cost-saving opportunities and ensure efficient use of resources', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'hardskill', 'CPMG')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://CSOP', 'Certification scheme operation', 'The overall purpose of certification for individuals is to recognise their competence to perform a specific task or job, or to determine whether they have met certain knowledge criteria. Knowledge and competence are distinct and the two terms should not be confused. A certification body is responsible for ensuring that only individuals who demonstrate competence are awarded certification. Certification of individuals provides value by building public confidence and trust. This confidence relies on a valid assessment of competence by a third party, which is reconfirmed at defined intervals. The certification body must act responsibly to provide confidence to interested parties in its competence, impartiality and integrity. Activities may include, but are not limited to: verifying, upon request, whether an individual holds a valid certificate and the scope of that certification, except where legal restrictions apply documenting security policies and procedures, including non-disclosure agreements or other measures to prevent the release of confidential examination materials or involvement in fraudulent practices implementing procedures for certified individuals to inform the certification body of any changes that could affect their ability to continue meeting certification requirements.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'hardskill', 'CSOP')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://CHMG', 'Change control', 'Change control is applied to all elements impacting live products, services or systems. This includes: applications, infrastructure, documentation, processes, configuration items and suppliers. Activities may include, but are not limited to: managing the change request lifecycle: registering, assessing, authorising, planning and deploying assessing risks and reducing risks to the availability, performance, security and compliance of the products and services impacted by the change developing processes for standard, normal or emergency changes developing methods and tools to automate change control processes to enable continuous integration.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'hardskill', 'CHMG')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://LEDA', 'Competency assessment', 'Competency assessment is a specialised practice for evaluating skills and competencies, distinct from performance appraisals and general capability understanding. Unlike performance reviews which focus on job performance and contributions, competency assessment objectively measures technical and professional capabilities. Assessments may be conducted in various contexts, including: recruitment, career progression, professional development planning, or accreditation/certification. Activities may include, but are not limited to: evaluating and selecting assessment options adopting or adapting assessment methods, tools and techniques considering the context of the assessment and how the results of the assessment will be used aligning assessments with ethical, legal and regulatory requirements. Ethical, legal and regulatory requirements are essential for ensuring the integrity of assessments and protecting personal data.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'softskill', 'LEDA')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://CFMG', 'Configuration management', 'Configuration items (CIs) can include a wide variety of components (objects) such as, but not limited to, source code, software, products, systems, hardware, networks, buildings, suppliers, process definitions and documents. A coherent set of CIs forms a configuration. Activities may include, but are not limited to: identifying and documenting the functional and physical characteristics of CIs identifying the relationships and maintain coherence between CIs for specific configurations identifying the associated configuration(s), status, version and other characteristics of CIs at distinct points in time controlling changes to CI characteristics, recording and reporting change processing and implementation status systematically controlling changes to a configuration and maintaining the integrity, coherence and traceability of that configuration throughout the project, system and/or service lifecycle adhering to established safety, security and quality standards verifying and auditing CI records for data quality and compliance with specified internal and external requirements.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'hardskill', 'CFMG')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://INCA', 'Content design and authoring', 'Content design and authoring encompasses a wide range of content types to meet user-centred and organisational needs. This includes textual information, graphical content and multimedia elements. Specific content types, include but are not limited to: website and mobile app content, user interface text, chatbot scripts, interactive content, social media content, email marketing, blog posts, online advertising copy and video scripts. Activities may include, but are not limited to: understanding the requirements of the intended audience collaborating with stakeholders and audience representatives to refine content needs applying tools and technologies to enhance content creation efficiency and quality implementing user-centred principles in content design, authoring and presentation considering information architecture, including how content is presented, identified and searched for managing the content design and authoring process coordinating with editorial and publication processes gathering source information and creating draft content identifying and integrating appropriate illustrations, graphics and multimedia elements understanding and applying copyright rules and related legal issues creating and using guidelines for clear, concise and accurate information presentation designing content collections across multiple media, including digital services and marketing materials.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'hardskill', 'INCA')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://ICPM', 'Content publishing', 'Information content may be in structured, unstructured or semi-structured forms. Activities may include, but are not limited to: understanding the requirements of the organisation and the target audience evaluating different publishing methods and options, and their costs, features and benefits, including open source and proprietary options developing and implementing a framework for content publishing, including preferred media, overall information structure and rules for formatting content identifying, briefing and collaborating with content creators converting content into a format suitable for publication delivering content to the user at the point of need managing copyright, data protection and other legal issues associated with publishing and re-using published information and data ensuring published material is in a form accessible to all potential users, including those with disabilities coordinating content across different platforms and ensuring consistent content presence across multiple platforms publishing new content or archiving outdated material.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'hardskill', 'ICPM')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://COPL', 'Continuity management', 'Activities may include, but are not limited to: identifying potential threats and assessing their business impact developing plans and procedures to respond to an incident ensuring critical business functions can continue with a planned level of disruption ensuring an acceptable level of service can be restored after a disruption developing organisational resilience assuring that continuity is being designed into systems, processes and ways of working implementing continuity management practices for cloud-based services enabling continuous delivery, deployment and integration of applications and infrastructure without adverse impact or disruption to service collaborating with external partners and suppliers to ensure continuity across the supply chain using technologies and tools for enhanced risk assessment, monitoring and decision-making regularly communicating and training staff on their roles and responsibilities during disruptive events. Incidents have a variety of causes, including, but not limited to: cyber-attacks, data breaches, organised crime, fires, floods, natural disasters, pandemics, health emergencies and supply chain failure.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'hardskill', 'COPL')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://ITCM', 'Contract management', 'Activities may include, but are not limited to: overseeing contracts from initiation and negotiation to renewal or termination ensuring effective communication and collaboration with internal teams, suppliers and clients maintaining alignment with laws, regulations and organisational policies evaluating contract performance against agreed metrics and key performance indicators (KPIs) managing contract variations and adjustments in response to evolving business needs or market conditions assessing and mitigating risks associated with contractual agreements integrating sustainability and ethical considerations into contract management using contract management software and tools for improved efficiency and accuracy incorporating contract management practices tailored to cloud-based services.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'hardskill', 'ITCM')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://CELO', 'Customer engagement and loyalty', 'Activities may include, but are not limited to: developing customer engagement and loyalty strategies establishing customer lifecycle communication strategies creating and managing customer loyalty programmes and initiatives managing customer data acquisition and profile augmentation analysing customer data to inform personalised communications and experiences developing customer journeys and segmentation strategies assessing and using marketing technology tools for customer engagement measuring and reporting on customer engagement and loyalty metrics collaborating with cross-functional teams to improve customer retention and satisfaction.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'hardskill', 'CELO')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://DATM', 'Data management', 'Activities may include, but are not limited to: developing and enforcing data governance policies to ensure data quality, compliance and ethical usage developing plans, policies and practices related to areas including, but not limited to, classification, storage, security, quality, sharing, availability, retrieval, retention and publishing managing data in all its forms, ensuring alignment with business objectives and regulatory requirements analysing information structures, including logical analysis of taxonomies, ontologies, data, metadata and industry reference data ensuring data is appropriately stored and archived, in line with relevant legislation implementing data management practices for cloud-based services applying ethical principles when handling data. developing innovative ways to manage data assets integrating data from multiple sources to support data pipelines and enable additional operations on the data.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'hardskill', 'DATM')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://DTAN', 'Data modelling and design', 'Data modelling supports activities such as, but not limited to: helping organisations understand their data assets, develop software systems and map relationships between real-world entities engaging with stakeholders to gather requirements and ensure data models align with business objectives facilitating data engineering, integration and interoperability enhancing data retrieval supporting data governance and master data management incorporating industry reference data standards to ensure consistency, interoperability and compliance. Data models typically include components such as entities, relationships, attributes and domains. There are various types of data models, including relational, object-oriented, NoSQL and time-based. Data models communicate different levels of detail, including conceptual, logical and physical.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'hardskill', 'DTAN')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://DEMM', 'Demand management', 'Activities may include, but are not limited to: collaborating with the business to prioritise demand to improve business value developing and communicating insights into patterns of demand performing what-if analyses and scenario planning to develop insights and proposals to improve business value proposing responses to meet both short-term and long-term demand and facilitating decision-making and planning integrating demand analysis and planning with complementary strategic, operational and change planning processes.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'hardskill', 'DEMM')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://DGFS', 'Digital forensics', 'Digital forensics involves the recovery, analysis, and investigation of material found in digital devices. This skill focuses on extracting and preserving digital evidence to support various types of investigations and legal proceedings. Activities may include, but are not limited to: collecting, processing, and analysing digital evidence from computers and other data storage devices applying specialised forensic tools and techniques to recover and examine digital material maintaining the integrity and chain of custody for all digital evidence reconstructing digital events and timelines to support investigative efforts documenting findings in comprehensive, legally defensible forensic reports presenting forensic evidence and testifying as an expert witness in legal proceedings collaborating with cybercrime investigators and legal teams to interpret technical evidence developing and implementing forensic methodologies for emerging technologies ensuring compliance with legal and ethical standards in digital evidence handling supporting various types of investigations, including security vulnerability assessments, criminal cases, fraud inquiries, and counterintelligence efforts.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'hardskill', 'DGFS')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://EMRG', 'Emerging technology monitoring', 'This skill involves systematically tracking, assessing and reporting on emerging technologies and their potential impact on the organisation. Activities may include, but are not limited to: conducting regular technology landscape scans evaluating potential benefits and risks of new technologies preparing reports and briefings for stakeholders on emerging trends recommending pilot projects or proofs of concept for promising technologies collaborating with research and development (R&D) teams to explore innovative applications attending industry conferences and engaging with technology vendors developing frameworks for assessing technology readiness and organisational fit advising on the strategic implications of adopting emerging technologies.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'hardskill', 'EMRG')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://EEXP', 'Employee experience', 'Activities may include, but are not limited to: providing opportunities for personal growth and learning providing sufficient personal freedom to decide how to achieve work objectives, with support available when needed supporting different views, working styles and behaviours within the work environment providing a safe and secure working environment with the resources needed to do the job providing transparent communications and building trust in leadership providing a holistic approach in support of mental and physical wellbeing. Note that the term employee is not limited to specific terms of employment. Depending on the employer it may include temporary and contract staff as well as salaried employees.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'softskill', 'EEXP')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://STPL', 'Enterprise and business architecture', 'Enterprise architecture is typically considered across four domains: business, data, applications and infrastructure technologies. It may also include information security or legal and regulatory compliance. Activities may include, but are not limited to: translating business strategies and objectives into an operating model assessing current capabilities and identifying required changes to achieve objectives developing and maintaining roadmaps to guide the transition from the current state to the future state describing the interrelationships between people, organisation, services, processes, data, information, technology and the external environment creating, iterating and maintaining architectural models and views that embody key principles for the organisation''s future state and evolution implementing enterprise architecture working practices to support and enable iterative/agile working interpreting business goals and drivers documenting and communicating constraints, standards and guiding principles necessary to define, assure and govern the required evolution using architectural models and processes to facilitate changes in the organisation''s structure, business processes, information or data, business systems and infrastructure describing where and why the enterprise will benefit from cloud-based services.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'hardskill', 'STPL')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://FEAS', 'Feasibility assessment', 'Activities may include, but are not limited to: generating and defining options ensuring options align with the organisation’s vision, mission, objectives, strategy and tactics engaging with relevant stakeholders and specialists evaluating options for financial, technical and business feasibility. Feasibility assessment is multi-dimensional. Options for change must be evaluated from several dimensions including, but not limited to: financial, technical, organisational capability and culture, strategic context, economic and/or commercial environment. Feasibility assessment typically results in a documented business case used to support organisational decision-making about proposed investments. This skill is focused on the generation, analysis and documentation of investment options.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'hardskill', 'FEAS')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://RSCH', 'Formal research', 'Activities may include, but are not limited to: determining research goals and the methods by which the research will be conducted actively participating in a community of researchers communicating formally and informally through digital media, conferences, journals, books and seminars. The Formal Research skill, as defined in SFIA, encompasses the systematic creation of new knowledge through rigorous methodologies, applicable across various sectors including, but not limited to, commercial research and development, academic institutions, governmental agencies, and non-profit organisations. Because of its name, this skill can be confused with general search and investigation into a topic of interest. In most cases, general investigations are covered by responsibilities described by the SFIA generic attributes. Many of the SFIA professional skills also refer to investigation or similar activity.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'hardskill', 'RSCH')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://TEST', 'Functional testing', 'Functional testing verifies that systems, components and interfaces deliver specific functionality, operate as intended and meet user expectations. Risk-based test planning and execution is a key aspect, focusing on identifying and mitigating risks such as functionality errors, integration failures, edge case defects, data inconsistencies and non-compliance with requirements. Activities may include, but are not limited to: collaborating with stakeholders to align testing with business requirements and objectives designing and adapting test cases based on requirements, including various scenarios, boundary values and edge cases preparing data and configuring environments to simulate realistic use cases executing tests to verify actual results align with expected outcomes logging defects with detailed reproduction steps, prioritising issues and providing feedback for improvements analysing results to identify patterns, assess quality and suggest system/testing enhancements promoting a shift-left approach by integrating functional testing early in the lifecycle for early issue detection managing, executing and automating tests, including regression and smoke tests, to improve efficiency and coverage developing and maintaining scalable, reliable automated tests and frameworks to validate critical functionality and ensure continuous quality ensuring compliance with industry standards, regulations and recognised good practices.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'hardskill', 'TEST')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://HWDE', 'Hardware design', 'The scope encompasses a wide range of hardware systems and components, including but not limited to processors, specialised computing units, embedded systems, control systems and various sensor and actuator devices. The hardware design should factor in integration needs with IT infrastructures, networking environments, as well as systems architectures such as cloud service models, edge computing and cyber-physical systems. Activities may include, but are not limited to: defining how hardware components fit into the system architecture and integrate with software, firmware and other systems selecting, designing, specifying, integrating and prototyping hardware components and subsystems considering target environments, performance, security, safety, reliability, sustainability and compatibility requirements adhering to industry standards including compatibility, safety, security, reliability and sustainability.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'hardskill', 'HWDE')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://HPCC', 'High-performance computing', 'High-performance computing (HPC) is the use of super computers and parallel processing techniques for solving complex computational problems. HPC technology focuses on developing parallel processing algorithms and systems. High-performance computing is typically used for solving advanced problems and performing research activities through computer modelling, simulation and analysis. Activities may include, but are not limited to: designing and optimising parallel algorithms managing and maintaining HPC infrastructures developing software for HPC environments conducting performance analysis and optimisation of HPC applications collaborating with researchers to translate scientific problems into HPC solutions. HPC technology is implemented in a variety of disciplines including, but not limited to: biosciences and molecular modelling geographical data oil and gas exploration climate modelling and weather forecasting physical simulations cryptanalysis. The terms high-performance computing and supercomputing are sometimes used interchangeably.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'hardskill', 'HPCC')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://IAMT', 'Identity and access management', 'Activities may include, but are not limited to: implementing identity and access management (IAM) frameworks in line with organisational goals and compliance with regulations like GDPR, HIPAA, or SOX streamlining user authentication with single sign-on solutions and enhancing security with multi-factor authentication managing user access rights from onboarding to offboarding, including integration with cloud services, enterprise applications and directory services like LDAP or Active Directory using role-based and attribute-based access controls to manage user privileges and access, aligning with organisational roles and attributes implementing privileged access management tools for secure monitoring and control of critical asset access handling incident responses related to access issues, like unauthorised access or identity theft regularly auditing access to maintain security and compliance conducting identity governance and administration to enforce policies, managing digital identities including user accounts, groups and roles.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'hardskill', 'IAMT')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://USUP', 'Incident management', 'Activities may include, but are not limited to: designing and implementing different processes and procedures for different categories of incidents including, but not limited to, major incidents, information or cybersecurity incidents, complex incidents and low impact incidents establishing incident response teams or security incident response teams enhancing preparedness through regular testing, training, simulations and development of incident response plans and playbooks restoring service to users as quickly as possible, prioritising service continuity over permanent solutions managing unplanned interruptions to a service or reductions in service quality routing requests for help to appropriate functions for resolution monitoring resolution activity ensuring compliance with regulations and data privacy requirements using automation and data-driven tools for earlier and faster incident detection and resolution informing users, customers and key stakeholders of progress towards service restoration. Incidents can impact areas such as business operations, information and cyber security, IT systems, services, employees, customers, or other vital business functions. Different roles or groups may be needed to diagnose and resolve incidents. These can include users, subject matter experts, service desk staff, support teams, suppliers, and partners. Although they participate in the incident management process, they do not necessarily require incident management skills.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'hardskill', 'USUP')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://PEDP', 'Information and data compliance', 'Includes legislation regulating the holding, use and disclosure of personal data. Activities may include, but are not limited to: providing expert advice on policies, procedures and governance designing privacy-friendly products, services and systems that respect customer privacy and embed data protection performing impact assessments, identify risks whilst enabling prudent use of data and addressing issues with products and services responding to incidents following legislative developments creating risk models and frameworks working with subject matter experts in areas such as, but not limited to, legal, public relations, learning and development, procurement, security, data management and architecture.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'hardskill', 'PEDP')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://INAS', 'Information assurance', 'Activities include, but are not limited to: management of risk in a pragmatic and cost-effective manner to ensure stakeholder confidence formal system certification and accreditation assessing the effectiveness of cryptographic controls technical assessment and evaluation to determine control effectiveness. Information and data are typically protected by following five principles: availability - ensuring authorised users can easily access the information they need integrity - protecting information from unauthorised modification, retrieval or deletion authenticity - validating the identity of users and devices confidentiality - restricting access to authorised users only non-repudiation - preventing possible denial that an action occurred by ensuring data is true to its origin.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'hardskill', 'INAS')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://ISCO', 'Information systems coordination', 'This skill is typically applied in large organisations with devolved information, data, technology, digital, cybersecurity functions or in collaborative enterprises of independent organisations. Activities may include, but are not limited to: developing and implementing strategies for coordinated deployment across multiple business units, such as, standardising hardware procurement, aligning software licensing and unifying cloud adoption approaches facilitating communication and collaboration between autonomous units identifying opportunities for shared services and integration coordinating enterprise-wide cybersecurity strategies and practices aligning initiatives with overall business objectives promoting standardisation of processes and technologies where beneficial managing cross-functional projects and initiatives evaluating and recommending enterprise-wide solutions developing governance frameworks for coordinated management of digital, data and technology.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'softskill', 'ISCO')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://IFDN', 'Infrastructure design', 'Technology infrastructure encompasses a wide range of components including, but not limited to: physical devices, virtual resources, cloud services, infrastructure-related software, middleware, network services and data storage solutions. The skill involves defining the components and services that make up the technology environment, their connections, interrelationships and operating parameters, which together ensure infrastructure solutions support current and future business needs. Activities may include, but are not limited to: developing detailed infrastructure design specifications and diagrams ensuring compatibility and integration between different infrastructure components designing infrastructure for scalability, performance, reliability and security from the outset ensuring designs adhere to industry standards, regulatory requirements and security protocols collaborating with stakeholders to align infrastructure design with business objectives maintaining comprehensive documentation of the design process and decisions integrating cloud services into the infrastructure design.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'hardskill', 'IFDN')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://ITOP', 'Infrastructure operations', 'Technology infrastructure encompasses a wide range of components including, but not limited to, physical devices, virtual resources, cloud services, infrastructure-related software, middleware, network services and data storage solutions. Infrastructure operations also involves implementing automation, cybersecurity measures and the adoption of cloud technologies to enhance efficiency, security and agility. These components may be on-premises, outsourced to third parties, or provisioned through cloud services. Activities may include, but are not limited to: provisioning and adapting infrastructure components to meet the evolving needs of users and service providers managing virtual, cloud and hybrid/multi-cloud environments automating tasks through scripting, coding, orchestration tools and infrastructure as code (IaC) practices ensuring infrastructure security through regular updates, patch management and adherence to cybersecurity policies and established industry practices monitoring infrastructure performance and its impact on efficiency, performance, security posture and sustainability collaborating with development teams (DevOps) using containerisation technologies to enhance application deployment and scalability.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'hardskill', 'ITOP')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://INOV', 'Innovation management', 'This skill focuses on a systematic, organisational approach to innovation. It is not describing personal behaviours, such as creativity. Activities may include, but are not limited to: developing and implementing processes, tools and infrastructures to support innovation implementing innovation practices to support iterative/agile working facilitating internal and external communities, employees, commercial partners, customers, users and other stakeholders in the innovation process providing a framework for governance, monitoring and reporting on the innovation process building a culture of experimentation and calculated risk-taking adopting strategies to incorporate external ideas and technologies to enhance and accelerate the organisation''s innovation efforts using data analytics to drive evidence-based innovation. developing metrics to measure innovation impact and return on investment.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'softskill', 'INOV')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://JADN', 'Job analysis and design', 'Activities may include, but are not limited to: gathering information and insights for current and future job requirements through methods such as surveys, interviews, workforce analytics and reviewing existing job documentation conducting task analysis to break down jobs into component roles and responsibilities, skills and competencies analysing workflow processes to design jobs that optimise efficiency, employee engagement and job satisfaction designing roles that support rapid team reconfiguration, upskilling and evolving in response to changing organisational needs and market demands creating or updating job architectures, job descriptions and specifications based on comprehensive analysis, organisational requirements and skills-based frameworks integrating new technologies, processes, or operational needs into job design, including the consideration of artificial intelligence and digital tools developing career pathways that align with professional development opportunities and organisational needs to aid staff retention. The scope of job analysis and design can range from single roles to multi-layered organisational structures.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'hardskill', 'JADN')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://ETMG', 'Learning and development management', 'Activities may include, but are not limited to: developing the full range of professional, business or technical capabilities required by the organisation developing learning and development strategies and policies identifying appropriate learning and development solutions, accreditations and qualifications selecting, tailoring and adopting skills and competency frameworks selecting and operating learning management systems administering, documenting, tracking and reporting on learning and development activities.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'softskill', 'ETMG')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://ETDL', 'Learning delivery', 'Learning delivery uses a variety of techniques, resources and media including: face-to-face learning, e-learning, online virtual environments, fieldwork and projects, self-assessment, peer-assisted learning and simulation. Typically, a blend of techniques will be used which can incorporate both formal and informal learning activities. Activities may include, but are not limited to: delivering learning content across various formats and platforms facilitating interactive learning sessions and workshops assessing learner progress and providing constructive feedback adapting delivery methods to suit different learning styles and needs incorporating new technologies and innovative approaches in learning delivery evaluating the effectiveness of learning delivery methods promoting a positive learning environment and encouraging learner engagement collaborating with subject matter experts and instructional designers.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'softskill', 'ETDL')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://TMCR', 'Learning design and development', 'Includes instructional design, content development, configuration and testing of learning environments, and use of appropriate current technologies such as audio, video, simulation and assessment. Scope includes learning and development activities for the workplace, for all levels of education and blended models such as apprenticeships and work placements. Activities may include, but are not limited to: specifying, designing, creating, packaging and maintaining materials and resources assimilating information from existing sources selecting and presenting material in a form suitable to the intended purpose and audience securing third-party accreditation creating simulated data and replicating external systems, interfaces, and assessment systems to support simulated learning environments.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'softskill', 'TMCR')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://MKCM', 'Marketing campaign management', 'Activities may include, but are not limited to: developing campaign strategies and selecting appropriate channels and tools writing creative briefs and evaluating creative concepts collaborating with internal teams and external agencies to develop compelling marketing content implementing and monitoring multi-channel marketing campaigns selecting appropriate tools and channels to reach target audiences developing and distributing marketing content and materials organising and participating in marketing events and initiatives analysing campaign performance and optimising for better results.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'hardskill', 'MKCM')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://MEAS', 'Measurement', 'Measurement can be applied to organisations, projects, processes and work products. Activities may include, but are not limited to: planning, implementation and control of activities to measure attributes of processes, products and services using measures to assess performance and progress and provide indications and insights to actual or potential problems, issues and risks identifying requirements for measurement implementing measurement to support iterative/agile working practices selecting measures and measurement scales, setting target values and thresholds establishing data collection and analysis methods, including automation real-time and near-real-time measurement. The measurement skill has diverse applications across industries, including customer experience, IT systems and services, marketing, supply chain, software development, finance, healthcare and project management.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'hardskill', 'MEAS')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://METL', 'Methods and tools', 'There is a wide range of methods and tools supporting areas such as, but not limited to, planning, development, testing, operation, management and maintenance of systems. The focus is on ensuring these methods and tools are not just available but are appropriately managed, refined and applied across the organisation to enhance efficiency, quality and consistency. Activities may include, but are not limited to: assessing, selecting and implementing methods and tools stewardship of methods and tools to enable effective use by others measuring, tailoring, improving and automating the use of methods and tools developing and maintaining documentation and user guides for methods and tools providing guidance, support and training for the adoption of new methods and tools evaluating the effectiveness of implemented methods and tools staying informed about industry developments related to methods and tools aligning methods and tools with organisational standards and good practices.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'hardskill', 'METL')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://NTAS', 'Network support', 'Activities may include, but are not limited to: monitoring network performance, investigating issues, troubleshooting and testing network devices implementing and managing network security measures, including access control, authentication, encryption and intrusion detection/prevention configuring and maintaining network solutions across physical, virtual and cloud environments automating network support tasks using scripting, automation tools and orchestration platforms creating and maintaining network documentation, including diagrams, configuration files and procedures providing technical support, advice and guidance to users and collaborating with others to resolve network issues analysing network performance, generating reports and presenting findings and recommendations to stakeholders collaborating with others to ensure seamless integration and operation across all environments.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'hardskill', 'NTAS')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://NFTS', 'Non-functional testing', 'Non-functional testing assesses the behaviour of technology, system components, configurations and packages, ensuring they work together to support the system''s operation. It focuses on identifying and mitigating risks related to system qualities and characteristics, such as performance, security, backup and recovery, availability, scalability, reliability, maintainability, monitoring, resource efficiency and compliance with technical standards. Activities may include, but are not limited to: collaborating with stakeholders to clarify non-functional requirements and expectations setting up test environments that mirror production conditions, simulating real-world usage preparing and managing test data to accurately represent necessary variety and volumes designing and executing stress, load, security and other non-functional tests troubleshooting issues during testing, coordinating with technical teams to resolve problems participating in reviews to refine non-functional requirements, identifying risks and suggesting enhancements analysing results to assess system performance, security and other key qualities, providing insights for improvement promoting a shift-left approach by integrating non-functional testing early in the lifecycle for early issue detection adapting testing strategies to suit various development methodologies developing and maintaining automated tests, monitoring systems and frameworks to continuously assess system quality and performance ensuring compliance with industry standards, regulations and recognised good practices.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'hardskill', 'NFTS')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://NUAN', 'Numerical analysis', 'Numerical analysis is the area of mathematics and computer science that creates, analyses and implements algorithms for numerically solving mathematical problems. Numerical analysis is required for applications including, but not limited to: simulations of physical systems machine learning data analytics Numerical analysis is concerned with: floating-point arithmetic and the resulting accumulation of rounding errors (integer arithmetic which has different considerations) consideration of the numerical stability, condition numbers, accuracy, computational complexity and usability of algorithms that solve mathematical problems. Activities may include, but are not limited to: developing and implementing numerical algorithms analysing and optimising the efficiency of numerical methods evaluating and improving the accuracy of computational results collaborating with domain experts to apply numerical solutions to real-world problems documenting and communicating complex numerical concepts to non-specialists.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'hardskill', 'NUAN')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://OCOP', 'Offensive cyber operations', 'Activities may include, but are not limited to: developing and executing strategies for offensive cyber operations selecting and profiling targets using intelligence and operational objectives creating and maintaining electronic target folders to organise target information coordinating and managing cyber operations, ensuring operational security evaluating intelligence cost versus operational benefit assessing potential collateral damage, including second and third-order effects conducting post-operation assessments and impact analysis. collaborating with intelligence and security teams to integrate operations with broader objectives.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'hardskill', 'OCOP')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://OCDV', 'Organisational capability development', 'Activities may include, but are not limited to: selecting, adopting and integrating appropriate industry frameworks and models to guide improvements using capability maturity assessments, metrics, process definition and process management building repeatable and reliable capabilities through a process of trial, feedback, learning and continual evolution developing appropriate techniques, tools and enhanced skills designing and delivering integrated people, process and technology solutions to deliver improved organisational performance in line with strategic plans and objectives identifying organisational priorities for enhancing performance, satisfying new business opportunities or responding to external drivers. The scope of improvement is typically organisation-wide but may also be highly focused on areas such as, but not limited to, business agility, software development, systems development, project delivery, service integration and management, service delivery, information and cyber-security.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'softskill', 'OCDV')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://OCEN', 'Organisational change enablement', 'Organisational change enablement is focused on the human and cultural aspects of change and supporting individuals and teams adapting to new work practices. The key elements are: stakeholder engagement for commitment, ongoing support for embedding changes and tailored communication addressing behavioural impacts and emotional readiness. Activities may include, but are not limited to: facilitating engagement sessions with leaders and managers to secure commitment to change initiatives defining communication strategies that address behavioural impacts and emotional readiness supporting individuals and teams in adopting new ways of working, providing resources for skill and behaviour development addressing and resolving issues during the implementation of change initiatives to ensure minimal disruption creating and managing networks of change agents to support and drive change advising leaders on monitoring and supporting behavioural change and addressing challenges establishing feedback processes to analyse the impact and effectiveness of change initiatives.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'softskill', 'OCEN')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://OFCL', 'Organisational facilitation', 'Activities may include, but are not limited to: developing and implementing team principles and practices for decision-making, prioritisation and problem-solving helping teams adopt new/contemporary working practices and behaviours including, but not limited to, specific agile methodologies, processes, tools and ceremonies helping teams plan and prioritise their workload based on their capacity and track record of working removing barriers or impediments to teams achieving their mission and objectives providing guidance and suggestions to support team members in adopting self-management and cross-functional working reviewing team effectiveness, identifying what went well, what could be improved, and what might be added or removed from their working practices. Workgroups may be focused on project, product or process management or may be focused on specific problems or deliverables. Workshop facilitation tools and techniques form part of applying this skill but are not sufficient. This skill describes a broader set of responsibilities.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'softskill', 'OFCL')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://ORDI', 'Organisation design and implementation', 'Activities may include, but are not limited to: facilitating changes needed to adapt to evolving technologies, societal shifts, new operating models and business processes defining and embedding key cultural attributes to enhance organisational performance designing and implementing new organisational structures, reporting lines and key parameters such as spans of control to align with strategic goals and improve adaptability aligning organisational design with business strategy and objectives, including digital transformation initiatives analysing skills gaps and developing strategies to address them, including upskilling and reskilling programmes facilitating cross-functional collaboration, promoting agile and flexible structures and reducing organisational silos applying tools such as design thinking, systems thinking, collaboration tools and data analytics in organisation design to inform decisions implementing organisational designs to improve responsiveness and adaptability. The scope of organisation design is broad, encompassing workplace environments, location strategies, role profiles, performance measurements, competencies, skills and the integration of new technologies.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'hardskill', 'ORDI')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://POMG', 'Portfolio management', 'Activities include, but are not limited to: alignment of investment with specific business strategies and objectives ensuring governance frameworks guide strategic investment appraisal and decision-making processes assessment of cost, risk, inter-dependencies and impact on existing business activities identifying issues with portfolio structure, cost, risk, inter-dependencies, impact on current business activities and the strategic benefits to be realised implementing portfolio management practices that support iterative/agile working measurement and objective evaluation of potential changes and the benefits to be realised prioritisation of resource utilisation and changes to be implemented regular review of portfolios management of the service pipeline (proposed or in development), service catalogue (live or available for deployment) and retired services.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'hardskill', 'POMG')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://PROF', 'Portfolio, programme and project support', 'Activities may include, but are not limited to: support the definition of portfolios, programmes and projects cultivating and applying new or changed working practices across a portfolio managing the rate at which new projects are started to fit the available capacity advising on the development, production and maintenance of business cases time, resource, cost and exception plans advising on the use of software tools tracking and reporting progress and performance facilitating portfolio/programme/project meetings and workshops advising and sharing knowledge on standards and how to comply.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'hardskill', 'PROF')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://PRTS', 'Process testing', 'Process testing focuses on ensuring systems effectively support business processes, deliver value and meet user needs. It involves identifying and mitigating risks such as inefficient or error-prone processes, unsupported user roles, restricted user actions, system complexity, inconsistent data handling and non-compliance with business requirements. Activities may include, but are not limited to: collaborating with stakeholders to align testing with business requirements and objectives designing test cases that cover entire business workflows, including business rules, alternate paths and exception scenarios setting up test environments that simulate real-world conditions, user roles and data flows preparing and managing test data to accurately support the scenarios being tested executing manual and automated tests to validate workflows, ensuring systems operate correctly across scenarios logging and reporting findings with an emphasis on business process impact, providing insights and recommendations analysing results to identify inefficiencies and areas for system and process enhancement promoting a shift-left approach by integrating process testing early in the lifecycle for early issue detection developing and maintaining scalable automation frameworks ensuring compliance with industry standards, regulations and recognised good practices.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'hardskill', 'PRTS')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://PROG', 'Programming/software development', 'Activities may include, but are not limited to: identifying, creating and applying software development and security standards and processes planning and designing software components estimating time and effort required for software development constructing, amending, and verifying software components, ensuring security is embedded applying test-driven development and ensuring appropriate test coverage using peer review techniques such as pair programming documenting software components understanding and obtaining agreement to the value of the software components to be developed selecting appropriate development methods and lifecycles applying recovery techniques to ensure the software being developed is not lost implementing appropriate change control to software development practices resolving operational problems with software and fixing bugs Depending on requirements and the characteristics of the project or assigned work, software development methods and lifecycles can be predictive (plan-driven) approaches or adaptive (iterative/agile) approaches.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'hardskill', 'PROG')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://RFEN', 'Radio frequency engineering', 'Activities may include, but are not limited to: evaluating and selecting devices and software integrating radio frequency (RF) sub-systems into larger systems calibrating, tuning and maintaining devices and software receiving, transmitting and converting data between analogue and digital devices, in accordance with industry and regulatory standards developing, integrating and configuring antennas, readers and transmitters in hardware or software forms, including software-defined radio (SDR), radio frequency identification (RFID), near field communication (NFC), Bluetooth and Wi-Fi adhering to established safety, security and quality standards. Applications of this skill include, but are not limited to: wireless local area networks wireless communication systems for voice, data and image, cellular radio systems, global positioning systems and military communications networks navigation and sensor systems.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'hardskill', 'RFEN')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://RELM', 'Release management', 'Activities may include, but are not limited to: planning and scheduling releases in line with business requirements, considering the size, scope and content of each release coordinating release activities across multiple teams and stakeholders, including third-party suppliers managing the release lifecycle, including build, testing, deployment and post-implementation review ensuring releases meet quality, security and compliance standards communicating release plans, progress and outcomes to stakeholders conducting post-release reviews and identifying areas for improvement maintaining release processes, procedures and documentation managing staged releases, pilot releases, blue/green releases or feature flags as appropriate.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'hardskill', 'RELM')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://REQM', 'Requirements definition and management', 'Requirements may be related to software, systems, data, processes, products or services. Activities may include, but are not limited to: eliciting and analysing requirements, both functional and non-functional ensuring customer requirements, priorities and acceptance criteria are accurately captured and validated organising and prioritising requirements using techniques such as, but not limited to, product roadmaps, epics, user stories and backlogs specifying and validating requirements, constraints and acceptance criteria to a level that enables effective development and operations of new or changed software, systems, processes, products or services negotiating trade-offs that are acceptable to key stakeholders and within budgetary, technical, regulatory and other constraints adopting and adapting requirements management lifecycle models. The requirements lifecycle approach will be based on the context of the work and may be selected from predictive (plan-driven) or adaptive (iterative/agile) approaches.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'hardskill', 'REQM')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://SFAS', 'Safety assessment', 'Activities may include, but are not limited to: making professional judgements on software and hardware engineering approaches assessing the suitability of design, testing and validation and verification methods identifying and evaluating risks and how they can be reduced establishing, maintaining and managing a safety assessment framework and practices using techniques such as failure modes effects analysis, hazard and operability studies, component failure impact analysis, fault tree analysis, event tree analysis and criticality analysis.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'hardskill', 'SFAS')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://SSUP', 'Sales support', 'Sales support can be delivered to a range of roles, such as, but not limited to, the sales force, sales agents, reseller/distributor staff and existing or prospective customers. This skill includes the provision of technical advice and assistance either in support of customer development or sales activity or in fulfilment of sales obligations. Activities may include, but are not limited to: providing technical information about products and services assisting in the preparation of sales proposals and presentations conducting product demonstrations responding to customer queries and providing solutions supporting the sales team in understanding customer requirements collaborating with other departments to resolve customer issues maintaining customer relationship management (CRM) systems assisting in post-sale support and customer onboarding.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'hardskill', 'SSUP')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://SEAC', 'Service acceptance', 'Service acceptance criteria are used to ensure a service meets the defined service requirements, including functionality, operational support, performance, safety, security and quality requirements. Acceptance criteria include both utility/functional and warranty/non-functional tests. Activities may include, but are not limited to: defining and documenting service acceptance criteria conducting service acceptance testing and evaluating test results against defined criteria ensuring the service provider is ready to operate the new service when it has been deployed providing feedback to service providers on necessary improvements documenting and reporting on service acceptance outcomes ensuring operational readiness for new or changed services implementing service acceptance practices to support iterative/agile working engaging with stakeholders to validate service readiness such as, but not limited to: external service providers, technical design, software development, DevOps and project management.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'hardskill', 'SEAC')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://SCMG', 'Service catalogue management', 'Activities may include, but are not limited to: publishing and maintaining information about available services tracking the list of available services as new services are introduced and current services are amended or retired making the catalogue useful and easy to use customising the information published for specific audiences, such as for users, for customers, for service providers supporting discussion of standard and non-standard service offerings enabling automation of service requests and service fulfilment where appropriate. The information documented in the service catalogue includes, but is not limited to, service names and descriptions, features, value propositions, costs, service support levels and availability.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'hardskill', 'SCMG')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://SLMO', 'Service level management', 'Activities may include, but are not limited to: planning, implementation, control, review and audit of service provision, to meet customer business requirements developing and managing both formal Service Level Agreements (SLAs) and less formal service expectations, depending on organisational needs and practices negotiating, implementing and monitoring service level agreements or service expectations managing operational facilities to provide the agreed levels of service identifying opportunities to improve service delivery implementing service level management practices to support cloud-based services identifying future trends and their impact on service delivery, for example, technical, market, industrial, socioeconomic, legislative or sustainability targets.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'hardskill', 'SLMO')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://PORT', 'Software configuration', 'This skill is typically applied to the design and deployment of configurations of large, complex software. This includes, but is not limited to: enterprise resource planning (ERP) and customer relationship management (CRM) software server/mainframe operating systems software as a service (SaaS) solutions integration platforms/suites tools provided by infrastructure as a service (IaaS) and platform as a service (PaaS) providers. Activities may include, but are not limited to: porting software configurations across different environments or platforms refactoring complex or overlapping configurations across different software modules and capabilities designing and implementing configurations that use architectures and services like microservices, serverless and containers optimising configurations for performance, scalability and cost-efficiency managing configurations across multiple environments and ensuring interoperability applying infrastructure as code principles to automate configuration deployment and management. Depending on requirements and the characteristics of the project or assigned work, software configuration methods and lifecycles can be predictive (plan-driven) approaches or adaptive (iterative/agile) approaches.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'hardskill', 'PORT')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://TECH', 'Specialist advice', 'This skill entails developing and using specialist knowledge to offer authoritative advice and direction, distinct from general guidance or troubleshooting. Professional advice is the provision of expert, objective and evidence-based recommendations, guidance and solutions to address specific challenges or opportunities, drawing upon the advisor''s in-depth knowledge, skills and experience. Expertise may cover a particular aspect of information or communications technology, digital practices, methodologies, or application areas and can extend to applying knowledge from other disciplines, such as legal, finance, public relations, ethics or human resources, to technology-related topics. Activities include, but are not limited to: research and analysis to stay current with the latest developments in the specialist area providing subject matter expert advice and recommendations based on thorough understanding of the subject collaborating with other specialists to ensure comprehensive and cohesive advice clearly communicating complex information to non-experts creating guidelines, standards and recommended practices related to the specialist area providing mentorship and guidance to support the development of specialist knowledge within the organisation.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'softskill', 'TECH')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://STMG', 'Storage management', 'Storage management encompasses managing various storage solutions, local or external storage such as direct access storage (DAS), network access storage (NAS), storage area networks (SAN) and cloud-based storage. It involves technologies and processes such as, but not limited to, virtualisation, replication, mirroring, security, compression, performance monitoring, automation and storage provisioning. Activities may include, but are not limited to: backup, archiving and recovery of data monitoring and optimising storage performance and capacity resolving potential and actual storage-related issues developing and maintaining tools and procedures for storage troubleshooting and analysis evaluating, provisioning and testing new storage solutions, including cloud-based storage managing storage in hybrid and multi-cloud environments investigating emerging technologies for storage management ensuring compliance with regulatory and security requirements addressing business goals based on information value, data classification, recovery point and recovery time objectives.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'hardskill', 'STMG')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://SUBF', 'Subject formation', 'Subject formation focuses on: developing curricula to support the development of understanding of the principles, approaches and practices that underpin specific topics and knowledge areas incorporating significant emerging technologies and techniques for which current students need to be prepared. The scope may include curricula for formal education or for independent examination bodies. This skill is generic and can be applied to curriculum design and development for any topic or knowledge area. In the context of the SFIA framework, this includes: the topics and knowledge areas that support any skills described in the SFIA framework and the application of these topics and knowledge areas to other disciplines and practices. In the context of computing and IT curricula, the topics addressed are typically: common digital skills needed to safely benefit from, participate in and contribute to the digital world for everyday life and for work fundamental and more advanced aspects of specific topics and knowledge areas including emerging technologies and new applications for existing technologies the ideas of computational thinking and the application of computational concepts to everyday life and professional working practices.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'softskill', 'SUBF')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://DESN', 'Systems design', 'A system is a structured arrangement of components, both physical and digital, designed to work together to meet specific requirements, considering factors such as scalability, security, human interaction and adherence to organisational and regulatory standards. Systems design activities may include, but are not limited to: using design concepts to develop a systems design and provide the basis for systems construction and verification designing or selecting system components designing systems compatible with contemporary computing architectures and selection of components such as cloud computing service models and edge computing designing cyber-physical systems that integrate computational and physical components considering human factors and socio-technical aspects when designing systems that involve significant human interaction developing a complete set of detailed models, properties and/or characteristics described in a form suitable for implementation adopting and adapting of system design lifecycle models based on the context of the work using predictive (plan-driven) approaches or adaptive (iterative/agile) approaches for system design adhering to regulatory requirements and organisational standards including security.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'hardskill', 'DESN')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://HSIN', 'Systems installation and removal', 'Systems or systems components may include, but are not limited to, hardware, software, cabling, wiring and monitoring equipment. Activities may include, but are not limited to: developing and following plans and instructions in accordance with agreed standards adhering to established safety, security and quality standards testing of hardware and software components, resolution of malfunctions and recording of results documenting the details of hardware and software installed so that configuration management records can be updated safe disconnection, decommissioning and removal of systems or system components.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'hardskill', 'HSIN')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://SINT', 'Systems integration and build', 'The scope of integration includes system elements, subsystems, interfaces and software components including computing, storage, networking and cloud services. Systems integration is used to create systems for testing purposes as well as for operational use by customers and users. Activities may include, but are not limited to: developing organisational capabilities, processes and procedures for automation and continuous integration of build, packaging, testing, security and deployment building and operating a continuous integration (CI) capability when required, employing version control of source code and related artefacts ensuring security and privacy requirements are an essential part of systems integration and build collaborating with development, testing and operations teams to streamline the integration process testing, validation and sign off of integration to satisfy requirements, architectures and design monitoring and controlling integration activities and recording and reporting on the results of integration keeping stakeholders informed and providing feedback into risk management processes developing and testing disaster recovery plans and applying incident management processes for major systems integrations.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'hardskill', 'SINT')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://SYSP', 'System software administration', 'System software encompasses a wide range of software components that support the functioning and management of technology infrastructure, including operating systems, infrastructure software, data management products, office automation products, middleware and utility software. It may run in cloud, virtual or physical hardware environments and enables applications to run effectively. Activities may include, but are not limited to: monitoring and optimising the performance of system software developing and maintaining diagnostic tools and procedures for system software troubleshooting and performance analysis resolving service problems with system software components evaluating, provisioning and testing new system software, including cloud based solutions reviewing system software updates and upgrades provisioning and testing system software updates and configurations adhering to established safety, security and quality standards managing system software in hybrid and multi-cloud environments.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'hardskill', 'SYSP')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://SLEN', 'Systems and software lifecycle engineering', 'This skill involves interdisciplinary approaches to developing and operating software and systems across their entire lifecycle. Commonly associated with terms such as DevOps, DevSecOps, site reliability engineering, developer productivity engineering. This skill extends beyond continuous improvement. It focuses on integrating technical practices and collaborative methods, automation and lifecycle processes essential for system reliability, security and operational excellence. Activities include, but are not limited to: establishing secure, reliable software lifecycle practices developing a supporting framework of methods, tools, processes, procedures and skilled personnel deploying this environment with teams responsible for developing and operating software and systems building repeatable, reliable capabilities through trial, feedback, learning and continual evolution adapting practices to specific products and services defining, controlling and improving lifecycle processes incorporating risk management, quality, security, privacy and safety maximising automation establishing architecture and design principles to support lifecycle processes focusing on mission, value and customer needs cultivating a culture of collaboration, learning, adaptation and resilience integrating industry frameworks to guide improvements.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'hardskill', 'SLEN')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://ITMG', 'Technology service management', 'Technology-based services may include, but are not limited to, IT infrastructure, audio-visual services, end-user computing, enterprise applications, facilities, communications services and industrial control systems. Activities may include, but are not limited to: approving, preparing, planning and managing new or changed services managing the performance of systems and services in terms of their contribution to business outcomes, financial costs and sustainability end-to-end management of services, whether delivered internally or sourced externally integrating internal and external services as well as delivery options leveraging multiple service delivery capabilities developing and implementing continual service improvement plans to ensure the technology services adequately support changing needs.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'hardskill', 'ITMG')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://BPTS', 'User acceptance testing', 'Activities include, but are not limited to: setting and applying standards for user acceptance testing (UAT) planning, identifying, designing, managing, executing and reporting on the outcomes of acceptance tests collaborating with a range of relevant stakeholders defining clear entry and exit criteria for UAT requesting and enabling formal acceptance of systems, products or services creating measurable acceptance criteria related to functional and non-functional requirements, features, business processes, user stories and business rules devising test cases and scenarios from acceptance criteria enabling exploratory testing to discover unexpected behaviours deploying model office testing to simulate real-world usage ensuring appropriate training for users involved in UAT providing input on UAT resource requirements, including necessary skills and availability. The acceptance testing approach will be based on the context of the work and may be selected from predictive (plan-driven) or adaptive (iterative/agile) approaches.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'hardskill', 'BPTS')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://UNAN', 'User experience analysis', 'This skill is inclusive of a full range of user tasks not just digital tasks. The skill can be applied in various contexts, such as: customer experience, products, services, applications, devices, learning experience and employee experience. Activities may include, but are not limited to: identifying, analysing, clarifying and communicating the context in which the product or service will be used describing users’ goals, tasks and the environment within which the systems, products, services or devices will be used creating and describing personas to represent key user segments developing user stories or requirements to describe features or capabilities agreeing user experience design goals analysing and prioritising user experience needs with stakeholders understanding and specifying user experience and user accessibility requirements for all potential users.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'hardskill', 'UNAN')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://HCEV', 'User experience design', 'This skill is inclusive of a full range of user tasks not just digital tasks. The skill can be applied in various contexts, such as, but not limited to customer experience, products, services, applications, devices, learning experience and employee experience. Activities may include, but are not limited to: understanding and addressing design goals, usability and accessibility requirements using an iterative design process to enhance user satisfaction by improving usability and accessibility designing digital and offline tasks, interactions and interfaces refining designs based on user experience evaluation communicating the design to those responsible for design, development and implementation of products, systems and services creating design artefacts such as sketches, ideas, storyboards, static wireframes, dynamic and workable prototypes developing alternative design and evaluating advantages, disadvantages, constraints and trade-offs considering and integrating appropriate visual design and branding elements into user experience design.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'hardskill', 'HCEV')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://USEV', 'User experience evaluation', 'This skill is inclusive of a full range of user tasks not just digital tasks. The skill can be applied in various contexts, such as, but not limited to customer experience, products, services, applications, devices, learning experience and employee experience. Evaluation is typically part of an iterative user experience design process and contributes to the improvement of the product or service. An evaluation can also be the starting point if an existing system, product or service is to be replaced or improved. Methods include user trials, expert review, survey and analysis. Activities may include, but are not limited to: providing assurance that user stories or requirements have been met and required practice has been followed to address accessibility, usability, security, health and safety applying a range of qualitative and quantitative evaluation techniques selecting from lightweight/rapid techniques or more thorough and resource-intensive approaches selecting appropriate use of formative or summative evaluations facilitating both moderated and unmoderated tests.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'hardskill', 'USEV')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://VUAS', 'Vulnerability assessment', 'Activities may include, but are not limited to: cataloguing and classifying information and technology resources (assets and capabilities) to support vulnerability assessment assigning quantifiable value, rank order and importance to information and technology resources identifying and analysing the vulnerabilities of each resource, manually or using automated tools and information sources prioritising, scoring and ranking the risk associated with vulnerabilities business impact assessment mitigating or eliminating the vulnerabilities. Vulnerability assessment tools include web application scanners, protocol scanners and network scanners.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'hardskill', 'VUAS')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://VURE', 'Vulnerability research', 'A security vulnerability is a weakness, flaw or error found within a security system that has the potential to be leveraged by an external agent to compromise a secure system. Activities may include, but are not limited to: researching new threats, attack vectors, risks and potential solutions researching new or emerging cryptographic vulnerabilities reverse engineering hardware or software applying tools such as disassemblers, debuggers and fuzzers analysing embedded devices developing techniques and tools to analyse and expose vulnerabilities designing new vulnerability discovery techniques sharing mitigation techniques with relevant stakeholders.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'hardskill', 'VURE')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;

INSERT INTO esco_dataset.habilidade (uri, nome, descricao, status, tipo_habilidade, nivel_reutilizacao, tipo_conceito, classificacao_habilidade, codigo)
VALUES ('sfia://WFPL', 'Workforce planning', 'Workforce planning typically takes an enterprise-wide view, assessing capabilities across the organisation rather than just a single team. The scope is more strategic than tactical resource allocation to projects or operational work schedules. Activities may include, but are not limited to: assessing the current state of the workforce assessing organisation-wide data over extended time periods to discover multi-year trends identifying critical capabilities needed to compete and meet strategic goals, not just immediate resource allocation gaps identifying the workforce required for current and future activities adopting or developing a skills and capabilities framework developing plans to close gaps between current state and future state using actions such as, but not limited to: external recruitment, internal development, re-skilling, sourcing external partners, organisational design or outplacement influencing organisational policies and practices to align recruitment, learning, promotion, and recognition and reward to support the development of an inclusive and diverse workforce adhering to relevant regulations and ethical standards concerning employment practices and organisational policies, including requirements related to layoffs and restructuring.', 'released', 'competencia', 'especifico_ocupacao', 'habilidade', 'hardskill', 'WFPL')
ON CONFLICT (uri) DO UPDATE SET nome = EXCLUDED.nome, codigo = EXCLUDED.codigo, descricao = EXCLUDED.descricao;


